import re
from typing import List, Dict, Tuple, Any, Optional

# ----------------------------------------------------------------------
# Helper utilities (unchanged)
# ----------------------------------------------------------------------
def node_by_title(doc: Dict[str, Any], title: str) -> Dict[str, Any]:
    for node in doc["nodes"]:
        if node.get("title") == title:
            return node
    raise KeyError(f"Title '{title}' not found")

def node_by_id(doc: Dict[str, Any], node_id: str) -> Dict[str, Any]:
    for node in doc["nodes"]:
        if node.get("node_id") == node_id:
            return node
    raise KeyError(f"Node id '{node_id}' not found")

def children(doc: Dict[str, Any], node: Dict[str, Any]) -> List[Dict[str, Any]]:
    return [node_by_id(doc, cid) for cid in node.get("children", [])]

def scope_nodes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    return children(doc, node_by_title(doc, scope))

def table_rows(node: Dict[str, Any]) -> List[Tuple[int, Dict[str, str]]]:
    rows = []
    for idx, row in enumerate(node.get("table", {}).get("rows", [])):
        row_dict = dict(zip(node["table"]["columns"], row))
        rows.append((idx, row_dict))
    return rows

# ----------------------------------------------------------------------
# Core functions
# ----------------------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """
    Return all distinct entities (objects) referenced inside the given scope.
    Each object line is parsed to obtain its id and description.
    """
    obj_node = None
    for n in scope_nodes(doc, scope):
        if n["kind"] == "list" and re.match(rf"{re.escape(scope)}: Objects$", n["title"]):
            obj_node = n
            break
    if obj_node is None:
        return []

    ents = []
    for line in obj_node["lines"]:
        m = re.match(r"Object (\d+): (.+)", line)
        if m:
            ents.append({"id": m.group(1), "description": m.group(2)})
    return ents


def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """
    Return the last frame number recorded in the motion log table.
    """
    mlog_node = None
    for n in scope_nodes(doc, scope):
        if n["kind"] == "table" and re.match(rf"{re.escape(scope)}: Motion log$", n["title"]):
            mlog_node = n
            break
    if not mlog_node:
        return None

    max_frame = None
    for _, row in table_rows(mlog_node):
        try:
            f = int(row["frame"])
            if max_frame is None or f > max_frame:
                max_frame = f
        except (ValueError, KeyError):
            continue
    return float(max_frame) if max_frame is not None else None


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Parse the 'Events' list node to generate input records for
    objects that are initially present or that enter the scene.
    """
    ent_map = {e["id"]: e["description"] for e in entities(doc, scope)}
    events_node = None
    for n in scope_nodes(doc, scope):
        if n["kind"] == "list" and re.match(rf"{re.escape(scope)}: Events$", n["title"]):
            events_node = n
            break
    if not events_node:
        return []

    inp = []
    c = 0

    def record(kind: str, t: float, eids: List[str], src: List[Any], fields: Dict[str, Any] = None):
        nonlocal c
        r = {
            "id": f"{scope}-in{c}",
            "time": t,
            "kind": kind,
            "entities": eids,
            "fields": fields or {},
            "src": src,
        }
        c += 1
        inp.append(r)

    for idx, line in enumerate(events_node["lines"]):
        # In view at frame 0
        m0 = re.match(r"Frame (\d+): Object (\d+).*is in view when the video begins", line)
        if m0:
            f, oid = int(m0.group(1)), m0.group(2)
            record("present", float(f), [oid], [events_node["node_id"], idx])
            continue
        # Enters the scene
        m1 = re.match(r"Frame (\d+): Object (\d+).*enters the scene", line)
        if m1:
            f, oid = int(m1.group(1)), m1.group(2)
            record("enter", float(f), [oid], [events_node["node_id"], idx])
            continue
    return inp


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Produce outcome records for:
        * Collisions
        * Exits
        * State samples from the motion log (speed)
    """
    events_node = None
    mlog_node = None
    for n in scope_nodes(doc, scope):
        if n["kind"] == "list" and re.match(rf"{re.escape(scope)}: Events$", n["title"]):
            events_node = n
        elif n["kind"] == "table" and re.match(rf"{re.escape(scope)}: Motion log$", n["title"]):
            mlog_node = n

    out = []
    c = 0

    def make(kind: str, t: float, eids: List[str], src: List[Any], val=None):
        nonlocal c
        r = {
            "time": t,
            "kind": kind,
            "entities": eids,
            "value": val,
            "src": src,
        }
        c += 1
        out.append(r)

    # Collisions and exits from events
    if events_node:
        for idx, line in enumerate(events_node["lines"]):
            m_col = re.match(r"Frame (\d+): Object (\d+).*collides with Object (\d+)", line)
            if m_col:
                f, o1, o2 = int(m_col.group(1)), m_col.group(2), m_col.group(3)
                make("collision", float(f), [o1, o2], [events_node["node_id"], idx])
                continue
            m_ex = re.match(r"Frame (\d+): Object (\d+).*exits the scene", line)
            if m_ex:
                f, oid = int(m_ex.group(1)), m_ex.group(2)
                make("exit", float(f), [oid], [events_node["node_id"], idx])
                continue

    # Motion‑log samples as state outcomes
    if mlog_node:
        for row_index, row in table_rows(mlog_node):
            try:
                f = float(row["frame"])
                obj_str = row["object"]
                oid = obj_str.split()[0]  # object id is first token
                speed = float(row["speed"])
                src = [mlog_node["node_id"], row_index]
                make("state", f, [oid], src, speed)
            except Exception:
                continue

    return out


